-- ============================================================
-- Devotional Summaries for "Journey Through Matthew" (30 days)
-- Run in Supabase SQL Editor after seed.sql
-- These UPDATE the passage_text for each day.
-- Leaders can override these via the admin Quest Builder.
-- ============================================================

UPDATE public.quest_days SET passage_text = 'Matthew traces Jesus'' family line all the way back to Abraham and David. This isn''t just a boring list of names — it''s proof that God keeps His promises across generations. Every name represents someone God used in His plan, and He''s using you too.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 1;

UPDATE public.quest_days SET passage_text = 'An angel appears to Joseph in a dream, telling him not to be afraid. Mary''s baby is from the Holy Spirit, and His name will be Jesus — meaning "God saves." Sometimes God asks us to trust Him even when things don''t make sense.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 2;

UPDATE public.quest_days SET passage_text = 'Wise men travel from far away to worship the newborn King, but King Herod sees Jesus as a threat. From the very beginning, Jesus attracted both worship and opposition. Following Jesus has always required courage.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 3;

UPDATE public.quest_days SET passage_text = 'John the Baptist bursts onto the scene calling people to repent and get ready for someone greater. Then Jesus shows up to be baptized — and God''s voice from heaven says, "This is my Son." When God speaks identity over Jesus, it changes everything.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 4;

UPDATE public.quest_days SET passage_text = 'Jesus faces the devil''s temptations in the wilderness and defeats each one with Scripture. He was hungry, tired, and alone — but He didn''t give in. When you know God''s Word, you have a weapon for every battle you''ll face.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 5;

UPDATE public.quest_days SET passage_text = 'Jesus begins the Sermon on the Mount with the Beatitudes — blessings for the humble, the merciful, the peacemakers. God''s kingdom flips the world''s values upside down. The people the world overlooks are the ones God calls blessed.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 6;

UPDATE public.quest_days SET passage_text = 'Jesus calls His followers to be salt and light — to make a difference wherever they go. He didn''t come to throw out God''s law but to fulfill it. Living for Jesus means standing out, not blending in.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 7;

UPDATE public.quest_days SET passage_text = 'Jesus raises the bar on anger, lust, and honesty. It''s not just about what you do — it''s about what''s going on in your heart. God cares about who you''re becoming on the inside, not just how you look on the outside.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 8;

UPDATE public.quest_days SET passage_text = 'Jesus teaches about loving your enemies, giving to the needy, and praying — not for show, but from a real heart. He even gives us a model prayer. God isn''t impressed by performance; He wants a genuine relationship with you.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 9;

UPDATE public.quest_days SET passage_text = 'Don''t worry about tomorrow — God feeds the birds and dresses the flowers, and you matter way more to Him. Seek His kingdom first, and everything else will fall into place. Anxiety shrinks when trust in God grows.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 10;

UPDATE public.quest_days SET passage_text = 'Jesus wraps up the Sermon on the Mount with a challenge: don''t just hear His words — do them. The wise builder and the foolish builder both faced the storm, but only one had a foundation that held. What are you building your life on?'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 11;

UPDATE public.quest_days SET passage_text = 'Jesus heals a leper, a centurion''s servant, and Peter''s mother-in-law. He has power over sickness and doesn''t turn anyone away — not even outsiders. No one is too far gone for Jesus to reach.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 12;

UPDATE public.quest_days SET passage_text = 'Jesus calms a raging storm with just His voice, then casts demons out of two men. His disciples are stunned: "What kind of man is this?" When life feels out of control, remember who''s in the boat with you.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 13;

UPDATE public.quest_days SET passage_text = 'Jesus calls Matthew — a tax collector everyone despised — to follow Him. Then He eats dinner with sinners and says, "I didn''t come for the healthy, but for the sick." Jesus meets you right where you are, not where you think you should be.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 14;

UPDATE public.quest_days SET passage_text = 'Jesus sends out His twelve disciples with authority to heal and preach. He warns them it won''t be easy but promises God''s care for every detail — even the hairs on their head. Following Jesus is risky, but you''re never alone in it.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 15;

UPDATE public.quest_days SET passage_text = 'John the Baptist, sitting in prison, sends a question to Jesus: "Are you really the one?" Jesus points to the evidence — the blind see, the lame walk, the good news is preached. Even heroes of faith have moments of doubt, and Jesus handles it with grace.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 16;

UPDATE public.quest_days SET passage_text = 'Jesus offers rest to everyone who is weary and burdened. His yoke is easy and His burden is light. Following Jesus isn''t about doing more — it''s about finding rest in the One who carries it all.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 17;

UPDATE public.quest_days SET passage_text = 'Jesus tells parables about the kingdom of God — seeds, weeds, mustard seeds, hidden treasure. God''s kingdom starts small but grows into something unstoppable. What looks insignificant to the world is priceless to God.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 18;

UPDATE public.quest_days SET passage_text = 'Jesus feeds 5,000 people with five loaves and two fish, then walks on water. Peter steps out of the boat but sinks when he takes his eyes off Jesus. Faith isn''t about having no fear — it''s about keeping your eyes on Jesus in the middle of it.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 19;

UPDATE public.quest_days SET passage_text = 'Peter declares that Jesus is the Christ, the Son of the living God. Then Jesus reveals that following Him means taking up your cross. The greatest confession of faith leads to the greatest call to sacrifice.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 20;

UPDATE public.quest_days SET passage_text = 'Jesus is transfigured on a mountain — His face shines like the sun and His clothes become white as light. Moses and Elijah appear. For one breathtaking moment, the disciples see Jesus for who He truly is: the glory of God in human form.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 21;

UPDATE public.quest_days SET passage_text = 'Jesus teaches about forgiveness with a parable: a servant is forgiven a massive debt but refuses to forgive a small one. God has forgiven you more than you could ever owe — how can you hold a grudge against someone else?'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 22;

UPDATE public.quest_days SET passage_text = 'A rich young man asks Jesus what he needs to do to have eternal life. Jesus tells him to sell everything and follow Him — but the man walks away sad. Money, status, comfort — what''s the thing you''re holding onto that keeps you from going all in with Jesus?'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 23;

UPDATE public.quest_days SET passage_text = 'Jesus tells the parable of the workers in the vineyard — everyone gets the same reward regardless of when they started. God''s generosity doesn''t follow our rules. His grace isn''t fair — it''s better than fair.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 24;

UPDATE public.quest_days SET passage_text = 'Jesus rides into Jerusalem on a donkey as crowds shout "Hosanna!" Then He clears the temple of money changers. The humble King arrives — but He''s not here to play nice with corruption. Jesus is gentle and fierce at the same time.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 25;

UPDATE public.quest_days SET passage_text = 'The religious leaders try to trap Jesus with tricky questions about taxes, marriage, and the law. Jesus silences them all with wisdom they can''t match. No matter what people throw at Him, Jesus always has the perfect answer.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 26;

UPDATE public.quest_days SET passage_text = 'Jesus warns about the end times and tells parables about being ready — wise virgins, faithful servants, sheep and goats. The message is clear: live like Jesus could return any moment. How you treat others reveals what you really believe.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 27;

UPDATE public.quest_days SET passage_text = 'Judas betrays Jesus. Peter denies Him three times. Jesus is arrested, beaten, and put on trial. The darkest night in history begins — but even in the darkness, God''s plan is unfolding exactly as it should.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 28;

UPDATE public.quest_days SET passage_text = 'Jesus is crucified between two criminals. He cries out, "My God, why have you forsaken me?" and then breathes His last. The Son of God dies — not because He was powerless, but because He loved you that much.'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 29;

UPDATE public.quest_days SET passage_text = 'The tomb is empty. Jesus is alive! He meets His disciples and gives them the Great Commission: "Go and make disciples of all nations." The story doesn''t end at the cross — it explodes into a mission that includes you. What will you do with the risen King?'
WHERE quest_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' AND day_number = 30;
